oxy_webhelp_navlinks = {"alerts_violations_agent_cloud-d39307e63680":{"topics":[{"title":"Viewing violation details","shortdesc":"<p class=\"shortdesc\">View details regarding policy violations, including the affected application, the         tool used, and the underlying LLM model.<\/p>","href":"agent_cloud\/alerts_violations_agent_cloud_all.html#viewing_violation_details","attributes":{"data-id":"viewing_violation_details"},"menu":{"hasChildren":false},"tocID":"viewing_violation_details-d39307e63691","topics":[]},{"title":"Viewing Alert Details","shortdesc":"<p class=\"shortdesc\">View comprehensive information about real-time activity alerts, including a summary,         application name, agent name, and date and time of the alert.<\/p>","href":"agent_cloud\/alerts_violations_agent_cloud_all.html#viewing_alert_details","attributes":{"data-id":"viewing_alert_details"},"menu":{"hasChildren":false},"tocID":"viewing_alert_details-d39307e63702","topics":[]},{"title":"Marking alerts and violations as safe","shortdesc":"<p class=\"shortdesc\">Mark an alert or a violation as safe when the activity it flagged is legitimate and         will recur. Marking as safe creates a policy exception that suppresses future alerts,         violations, and blocks for a specific tool or agent.<\/p>","href":"agent_cloud\/alerts_violations_agent_cloud_all.html#marking_alerts_violations_safe","attributes":{"data-id":"marking_alerts_violations_safe"},"menu":{"hasChildren":false},"tocID":"marking_alerts_violations_safe-d39307e63713","topics":[]}]}};